/** Retained stage433 budget counterexample must complete AND pass fresh independent replay at same limit. */
public final class ContextUniversalGroupedSessionBudgetRunner {
    static int checks;static final int WORK=64000000;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    public static void main(String[] args){try {
        System.setProperty("user.home",java.nio.file.Files.createTempDirectory("grouped-session-budget-").toString());Snapshot x=ContextUniversalGroupedRoundsRunner.bind(true,"!anchor(1); !@u p(u);"),a=ContextUniversalGroupedRoundsRunner.bind(false,"!@u (p(u)&&b(u)->r(u))&&(p(u)&&r(u)->s(u));"),b=ContextUniversalGroupedRoundsRunner.bind(false,"!b(1);");Packet p=ContextPrivateWitnessPoolRunner.common(x);List<Snapshot> cuts=Arrays.asList(a,b);ContextUniversalCompoundExchange.Exchange input=ContextUniversalGroupedRoundsRunner.exchange(x,cuts,p,Collections.emptyMap());ContextUniversalSignedUnitExchange.Exchange units=ContextUniversalGroupedRoundsRunner.units(input);ContextUniversalFrozenBranch.Limits limits=ContextUniversalGroupedRoundsRunner.limits(16);ContextUniversalGroupedLocalRounds.Limits local=ContextUniversalGroupedRoundsRunner.local();
        ContextUniversalGroupedRounds.SessionRun checked=ContextUniversalGroupedRounds.runWithValidationReuse(x,cuts,p,Collections.emptyMap(),units,input,limits,local,8,WORK,4096);ContextUniversalGroupedRounds.Result r=checked.result;require(r.status==ContextUniversalGroupedRounds.Status.STABLE_GROUPED_POOLS&&r.completedRounds==3&&r.history.size()==3&&r.output!=null&&r.refutations.isEmpty(),r.phase+": "+r.reason);require(checked.metrics.entries==0&&checked.metrics.work<WORK&&checked.metrics.hits>0&&checked.metrics.peakEntries<=4096,"same cumulative64m budget, released bounded memo");
        require(ContextUniversalGroupedRoundsRunner.has(r.output.packet,"r")&&ContextUniversalGroupedRoundsRunner.has(r.output.packet,"s")&&!ContextUniversalGroupedRoundsRunner.has(r.output.packet,"b"),"actual X-dependent r/s products, no raw b publication");require(r.output.packet.items.stream().filter(i->i.atom.predicate.equals("r")).flatMap(i->i.proofs.stream()).anyMatch(s->s.depth==1&&s.sources.size()==3)&&r.output.packet.items.stream().filter(i->i.atom.predicate.equals("s")).flatMap(i->i.proofs.stream()).anyMatch(s->s.depth==2&&s.sources.size()==3),"whole shared physical producer Source retained at true r1/s2 minima");
        ContextUniversalGroupedChainAudit.SessionInspection audit=ContextUniversalGroupedChainAudit.inspectWithValidationReuse(x,cuts,p,Collections.emptyMap(),units,input,limits,local,8,r,WORK,4096);require(audit.inspection.audited&&audit.inspection.output!=null,audit.inspection.phase+": "+audit.inspection.reason);require(audit.metrics.entries==0&&audit.metrics.verified>0&&audit.metrics.hits>0,"independent session does not inherit the controller memo");require(ContextUniversalGroupedChainAudit.checkWithValidationReuse(audit.inspection.output,WORK,4096).verified>0,"a receipt recheck starts another real validation");
        ContextUniversalGroupedRounds.SessionRun again=ContextUniversalGroupedRounds.runWithValidationReuse(x,cuts,r.output.packet,r.output.privatePools,r.symbolicOutput,r.compoundOutput,limits,local,1,WORK,4096);ContextUniversalGroupedRounds.Result one=again.result;
        require(one.status==ContextUniversalGroupedRounds.Status.STABLE_GROUPED_POOLS&&one.completedRounds==1&&one.history.size()==1&&one.output!=null&&one.symbolicOutput!=null&&one.compoundOutput!=null&&one.refutations.isEmpty(),one.phase+": "+one.reason);require(again.metrics.entries==0&&again.metrics.work<WORK,"whole first continuation closes its own bounded session");
        require(ContextWitnessResultTransport.sameContents(one.output.packet,r.output.packet,WORK)&&ContextUniversalSignedUnitExchange.sameContents(one.symbolicOutput,r.symbolicOutput,WORK)&&ContextUniversalCompoundExchange.sameContents(one.compoundOutput,r.compoundOutput,WORK),"same exact fixed/unit/compound Source-depth minima after continued stable barrier");
        ContextUniversalGroupedChainAudit.SessionInspection resumedAudit=ContextUniversalGroupedChainAudit.inspectWithValidationReuse(x,cuts,r.output.packet,r.output.privatePools,r.symbolicOutput,r.compoundOutput,limits,local,1,one,WORK,4096);require(resumedAudit.inspection.audited&&resumedAudit.inspection.output!=null,resumedAudit.inspection.phase+": "+resumedAudit.inspection.reason);require(resumedAudit.metrics.entries==0&&resumedAudit.metrics.verified>0&&resumedAudit.metrics.hits>0,"fresh independent audit of SAME first continued trace");require(ContextUniversalGroupedChainAudit.checkWithValidationReuse(resumedAudit.inspection.output,WORK,4096).verified>0,"continued receipt recheck authenticates again in another fresh session");
        ContextUniversalGroupedRounds.SessionRun next=ContextUniversalGroupedRounds.runWithValidationReuse(x,cuts,one.output.packet,one.output.privatePools,one.symbolicOutput,one.compoundOutput,limits,local,1,WORK,4096);require(next.result.status==ContextUniversalGroupedRounds.Status.INCOMPLETE&&next.result.phase.equals("checks")&&next.result.completedRounds==0&&next.result.output==null&&next.result.symbolicOutput==null&&next.result.compoundOutput==null&&next.result.history.isEmpty()&&next.result.refutations.isEmpty()&&next.result.reason.contains("Ground transport work limit"),"SECOND continuation kernel-owned budget remains explicit refusal: "+next.result.phase+": "+next.result.reason);require(next.metrics.entries==0&&next.metrics.work<WORK,"second owning memo closes; refusal belongs to separate signed-close budget");
        ContextUniversalFrozenConstraints.Result self=ContextUniversalFrozenConstraints.closeSignedCompounds(ContextUniversalCompoundExchangeRunner.rows(x,null),one.output.packet,null,one.symbolicOutput,one.compoundOutput,16,16,512,256,WORK);require(!self.closed&&self.proofs.isEmpty()&&self.emptyProofs.isEmpty()&&self.reason.contains("Ground transport work limit"),"same actual SECOND self-X base closure independently refuses without proof prefix: "+self.reason);
        System.out.println("SESSION_CONTINUATION_STABLE rounds="+one.completedRounds+" controllerWork="+again.metrics.work+" auditWork="+resumedAudit.metrics.work+" auditVerified="+resumedAudit.metrics.verified);
        System.out.println("SESSION_SECOND_CONTINUATION_REFUSAL phase="+next.result.phase+" controllerWork="+next.metrics.work+" reason="+next.result.reason);System.out.println("SESSION_SECOND_SELF_CHECK_REFUSAL reason="+self.reason);
        System.out.println("SESSION_RETAINED_BUDGET rounds="+r.completedRounds+" controllerWork="+checked.metrics.work+" controllerHits="+checked.metrics.hits+" controllerVerified="+checked.metrics.verified+" auditWork="+audit.metrics.work+" auditVerified="+audit.metrics.verified);
        System.out.println("CONTEXT_UNIVERSAL_GROUPED_SESSION_BUDGET_PASS checks="+checks);System.exit(0);
    }catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
